# region: render
def render(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
        return out
    return out

# region: gather
def gather(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: digest
def digest(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(gather(intake(render(raw))))

